UPDATE public."SSP_Facility_Booking" b SET created_at = (c.value->>'original_created_at')::timestamptz FROM candidates c
WHERE b.name::text=c.value->'booking_backup'->>'name'
AND to_jsonb(b)=c.value->'booking_backup'
AND EXISTS (SELECT 1 FROM public."SSP_Facility_Booking_Request" r WHERE r.request_id::text=c.value->>'request_id' AND r.payment=b.payment AND r.created_at=(c.value->>'original_created_at')::timestamptz)
RETURNING b.name,b.created_at;
